// Generado como TTF desde las mismas fuentes locales de la web; uso exclusivo del PDF en servidor.
const regular = '';
const titulos = '';
const bytes = (base64: string) => Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));
export const fuentesPdf = () => ({ regular: bytes(regular), titulos: bytes(titulos) });
